#!/usr/bin/env python3
"""
Round 217o (culprits), 16 October 2026. Needs round 216o.

Sunlight's reach in 3D, its bodies grouped with the life switch; the sky made
readable; the Sun view's planets on; the views open straight away; place
names first; bigger Moon and Mars marks; listed worlds on the biosignature ring.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 217o (16 October)\n\nNeeds round 216o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Sunlight\'s reach: a 3D view (globe.gl with the globe hidden; the Sun at the\n  centre; rings every tenfold distance in the galaxy\'s plane; bodies at their\n  galactic longitude and latitude; stars as particles; names as HTML marks\n  that open their boxes). Its body rows sit in one folding group, "Celestial\n  bodies the Sun\'s light reaches", with a group tick and the "Show only\n  worlds that could hold life" switch beside its title (the View box option\n  is gone).\n- Sky: rows in the order the Sun, Moon and planets; other stars; galaxies,\n  clusters and nebulae, in plain words; a "How to read this map" box at the\n  top (open by default) and a key to colours and sizes. Stars are coloured by\n  their own light, sized by the light reaching Earth. The basemaps now tint\n  the stars (the overlay pane, and the 3D globe\'s picture). Views named "Flat\n  chart" and "3D globe".\n- Sun view: planets on from the main map\'s row too (bodyLayers objects and\n  planets); opens on Uranus\'s orbit.\n- The Moon, Mars, Sun, sky and Sunlight\'s reach views open straight away\n  from their rows (leaveEarth(true): no pass through Eyes; Eyes waits behind).\n- Place names first in the Moon and Mars views and on the main map.\n- Moon and Mars globe marks grow with the viewing distance.\n- Biosignature ring: with every world in Wikipedia\'s two lists (tiles\n  bodies/reach/life.json), small and grey-blue, placed on the page\'s own\n  distance rail between its worlds by distance from Earth, unassessed, every\n  column in its box; Earth and worlds with no distance left off.\n\n']

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round217o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 216o" not in h.read_text(encoding="utf-8"):
        sys.exit("round217o: round 216o must be applied first (round216o_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round217o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/bodies.html", "map/test.mjs", check=False)
            sys.exit("round217o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round217o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
